function structureCollides(x,z,r){for(const item of interactables){if(item.kind!=='door'||item.state)continue;const b=item.collider,dx=Math.max(Math.abs(x-b.x)-b.w/2,0),dz=Math.max(Math.abs(z-b.z)-b.d/2,0);if(dx<r&&dz<r)return true}return false}
function setStructureState(item,open){if(item.state===open)return;item.state=open;item.pivot.rotation.y=open?(item.kind==='door'?Math.PI/2:(Math.abs(item.x-sites[item.siteIndex].x)<.1?Math.PI/2:-Math.PI/2)):0;try{savedStructures[item.key]=open;localStorage.setItem('elsewhere-structures',JSON.stringify(savedStructures))}catch{}}
function npcCollides(x,z,r=.6){if(Math.abs(x)>112||Math.abs(z)>94)return true;for(const b of walls){const dx=Math.max(Math.abs(x-b.x)-b.w/2,0),dz=Math.max(Math.abs(z-b.z)-b.d/2,0);if(dx<r&&dz<r)return true}return structureCollides(x,z,r)}

