function activitySite(npc,activity){if(activity==='sleep'||activity==='home')return npc.homeSite??-1;if(activity==='work'||activity==='commute')return npc.workSite??-1;if(activity==='eat'&&hourOfDay()>=6&&hourOfDay()<8)return npc.homeSite??-1;return-1}
function sitePoint(siteIndex,outside=false){const s=sites[siteIndex];return{x:s.x,z:s.z+(outside?(s.d||10)/2+1.65:0)}}
function currentNpcSite(npc){return sites.findIndex(s=>Math.abs(npc.x-s.x)<(s.w||12)/2-.8&&Math.abs(npc.z-s.z)<(s.d||10)/2-.8)}
function anchorFor(npc,activity){const i=npcState.indexOf(npc),siteIndex=activitySite(npc,activity);if(siteIndex>=0)return sitePoint(siteIndex);if(activity==='social')return{x:meetSpots[i][0],z:meetSpots[i][1]};if(activity==='eat'){const p=foodSpots[i];return{x:p[0],z:p[1]}}return{x:npc.homeX,z:npc.homeZ}}
function roadPath(start,end){const xs=[-88,-58,-28,2,32,62,92],zs=[-72,-42,-12,18,48,78],nearest=(values,n)=>values.reduce((a,b)=>Math.abs(b-n)<Math.abs(a-n)?b:a,values[0]),rx=nearest(xs,start.x),rz=nearest(zs,start.z),ex=nearest(xs,end.x),ez=nearest(zs,end.z);return[{x:rx,z:start.z},{x:rx,z:rz},{x:ex,z:rz},{x:ex,z:ez},{x:end.x,z:ez},end]}
function planNpcRoute(npc){const source=currentNpcSite(npc),destination=activitySite(npc,npc.activity),points=[];if(source>=0&&source!==destination){const exit=sitePoint(source,true);points.push(exit);if(destination<0){points.push(...roadPath(exit,npc.anchor).slice(1))}}if(destination>=0&&source!==destination){const entrance=sitePoint(destination,true);const start=points.at(-1)||{x:npc.x,z:npc.z};points.push(...roadPath(start,entrance).slice(1),sitePoint(destination))}else if(destination<0&&source<0)points.push(npc.anchor);npc.destinationSite=destination;npc.route=points.filter((p,i)=>!i||Math.hypot(p.x-points[i-1].x,p.z-points[i-1].z)>.35);npc.target=npc.route.shift()||{x:npc.anchor.x,z:npc.anchor.z}}
function chooseNpcTarget(npc,still=false){if(still){npc.route=[];npc.target={x:npc.anchor.x,z:npc.anchor.z};return}for(let i=0;i<18;i++){const ang=rand()*Math.PI*2,radius=.25+rand()*(npc.activity==='social'?1.3:.85),x=npc.anchor.x+Math.cos(ang)*radius,z=npc.anchor.z+Math.sin(ang)*radius;if(!npcCollides(x,z,.62)){npc.target={x,z};return}}npc.target={x:npc.anchor.x,z:npc.anchor.z}}

